/**
 * Unit tests for FitnessFunction.repairAndDecode.
 * Since FitnessFunction is an inner class of CMAESOptimizer and the method 
 * simply delegates to decode(x), we test the functional behavior and delegation.
 */
public class FitnessFunction_repairAndDecode_TriageGen1Test {

    private CMAESOptimizer.FitnessFunction fitnessFunction;

    @Before
    public void setUp() {
        // In a real scenario, FitnessFunction might be a non-static inner class.
        // Assuming standard instantiation based on the provided signature.
        fitnessFunction = new CMAESOptimizer.FitnessFunction();
    }

    @Test
    public void testRepairAndDecode_WithValidArray() {
        double[] input = {1.0, 2.0, 3.0};

        // Since repairAndDecode calls decode(x), we verify the result matches decode's output.
        // In a pure unit test without mocking the internal decode (if it's private), 
        // we test the end-to-end flow.
        double[] expected = fitnessFunction.decode(input);
        double[] actual = fitnessFunction.repairAndDecode(input);

        assertArrayEquals(expected, actual, 1e-10);
    }

    @Test
    public void testRepairAndDecode_WithEmptyArray() {
        double[] input = {};

        double[] expected = fitnessFunction.decode(input);
        double[] actual = fitnessFunction.repairAndDecode(input);

        assertArrayEquals(expected, actual, 1e-10);
    }

    @Test
    public void testRepairAndDecode_WithLargeValues() {
        double[] input = {Double.MAX_VALUE, Double.MIN_VALUE, 0.0};

        double[] expected = fitnessFunction.decode(input);
        double[] actual = fitnessFunction.repairAndDecode(input);

        assertArrayEquals(expected, actual, 1e-10);
    }

    @Test
    public void testRepairAndDecode_WithNegativeValues() {
        double[] input = {-1.0, -5.5, -100.0};

        double[] expected = fitnessFunction.decode(input);
        double[] actual = fitnessFunction.repairAndDecode(input);

        assertArrayEquals(expected, actual, 1e-10);
    }

    @Test(expected = NullPointerException.class)
    public void testRepairAndDecode_WithNullInput() {
        // Testing the behavior when null is passed, 
        // as decode(x) will likely throw NPE if it accesses x.length
        fitnessFunction.repairAndDecode(null);
    }
}
